-- SCIEM — Script de creación de la base de datos
-- Versión 4 (public). Cambios respecto de V3:
--   * Esquema `modelinicial` reemplazado por `public`.
--   * PKs surrogate con GENERATED BY DEFAULT AS IDENTITY.
--   * public.usuario.id_usuario con DEFAULT gen_random_uuid().
--   * Extensión pgcrypto habilitada (requerida por gen_random_uuid).

CREATE SCHEMA IF NOT EXISTS public;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

---------------------------------------------------
-- ENUMS
---------------------------------------------------

CREATE TYPE public.estado_registro AS ENUM (
    'ACTIVO',
    'INACTIVO'
);

CREATE TYPE public.estado_habilitacion AS ENUM (
    'HABILITADO',
	'CASO ESPECIAL',
    'NO_HABILITADO'
);

CREATE TYPE public.estado_ingreso AS ENUM (
    'INGRESO',
    'CON_RETRASO',
    'NO_INGRESO'
);

CREATE TYPE public.estado_invitacion AS ENUM (
    'PENDIENTE',
    'ACEPTADA',
    'RECHAZADA'
);

CREATE TYPE public.estado_reporte AS ENUM (
    'PENDIENTE',
    'APROBADO',
	'RECHAZADO'
);

CREATE TYPE public.categoria_examen AS ENUM (
    'REGULAR',
    'MESA',
	'ADMISION'
);

-- Ciclo de vida del examen (HU-24). Solo PROGRAMADO y CANCELADO se alcanzan hoy;
-- EN_INGRESO, EN_CURSO y FINALIZADO los asignan las historias de control de ingreso.
CREATE TYPE public.estado_examen AS ENUM (
    'PROGRAMADO',
    'EN_INGRESO',
    'EN_CURSO',
    'FINALIZADO',
    'CANCELADO'
);

---------------------------------------------------
-- accion
---------------------------------------------------

CREATE TABLE public.accion (
    id_accion       integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    operacion       varchar(100) NOT NULL,
    tipo_operacion  varchar(10) NOT NULL,
    descripcion     text,

    CONSTRAINT pk_accion
        PRIMARY KEY (id_accion)
);

---------------------------------------------------
-- ambiente
---------------------------------------------------

CREATE TABLE public.ambiente (
    id_ambiente     integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nro_aula        varchar(10) NOT NULL,
    capacidad       integer NOT NULL,
    ubicacion       text,
    estado          public.estado_registro NOT NULL,

    CONSTRAINT pk_ambiente
        PRIMARY KEY (id_ambiente),

    CONSTRAINT chk_ambiente_capacidad
        CHECK (capacidad > 0),
	
	CONSTRAINT unq_ambiente_nro_aula
    UNIQUE (nro_aula)
);

---------------------------------------------------
-- estudiante
---------------------------------------------------

CREATE TABLE public.estudiante (
    id_estudiante        integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    cod_sis              varchar(15) NOT NULL,
    -- NULL hasta la primera verificación (EX04): la nómina no trae el CI.
    ci                   varchar(10),
    nombre               varchar(50) NOT NULL,
    apellido_paterno     varchar(30) NOT NULL,
    apellido_materno     varchar(30),
    correo_institucional varchar(100),
    telefono             varchar(8),
    estado               public.estado_registro NOT NULL,

    CONSTRAINT pk_estudiante
        PRIMARY KEY (id_estudiante),

    CONSTRAINT unq_estudiante_cod_sis
        UNIQUE (cod_sis),

    CONSTRAINT unq_estudiante_ci
        UNIQUE (ci)
);

---------------------------------------------------
-- facultad
---------------------------------------------------

CREATE TABLE public.facultad (
    id_facultad  integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nombre       varchar(50) NOT NULL,
    codigo       varchar(50) NOT NULL,
    descripcion  text,
    estado       public.estado_registro
                 DEFAULT 'ACTIVO' NOT NULL,

    CONSTRAINT pk_facultad
        PRIMARY KEY (id_facultad),

    CONSTRAINT unq_facultad_codigo
        UNIQUE (codigo)
);

---------------------------------------------------
-- materia
---------------------------------------------------

CREATE TABLE public.materia (
    id_materia   integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nombre       varchar(50) NOT NULL,
    codigo       varchar(50) NOT NULL,
    descripcion  text,
    estado       public.estado_registro
                 DEFAULT 'ACTIVO' NOT NULL,

    CONSTRAINT pk_materia
        PRIMARY KEY (id_materia),

    CONSTRAINT unq_materia_codigo
        UNIQUE (codigo)
);

---------------------------------------------------
-- periodo
---------------------------------------------------

CREATE TABLE public.periodo (
    id_periodo      integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nombre_periodo  varchar(10) NOT NULL,
	gestion			smallint    NOT NULL,

    CONSTRAINT pk_periodo
        PRIMARY KEY (id_periodo),

    CONSTRAINT unq_periodo_nombre
        UNIQUE (nombre_periodo),

    CONSTRAINT chk_periodo_gestion
        CHECK (gestion BETWEEN 1900 AND 2200)
);

---------------------------------------------------
-- permiso
---------------------------------------------------

CREATE TABLE public.permiso (
    id_permiso      integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nombre_permiso  varchar(80) NOT NULL,
    descripcion     text,
    estado          public.estado_registro
                    DEFAULT 'ACTIVO' NOT NULL,

    CONSTRAINT pk_permiso
        PRIMARY KEY (id_permiso),

    CONSTRAINT unq_permiso_nombre
        UNIQUE (nombre_permiso)
);

---------------------------------------------------
-- postulante
---------------------------------------------------

CREATE TABLE public.postulante (
    id_postulante    integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
