);

---------------------------------------------------
-- tipo_falta
---------------------------------------------------

CREATE TABLE public.tipo_falta (
    id_falta      integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nombre        varchar(30) NOT NULL,
    descripcion   text,

    CONSTRAINT pk_tipo_falta
        PRIMARY KEY (id_falta),

    CONSTRAINT unq_tipo_falta_nombre
        UNIQUE (nombre)
);

---------------------------------------------------
-- ui
---------------------------------------------------

CREATE TABLE public.ui (
    id_ui        integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nombre_ui    varchar(100) NOT NULL,
    descripcion  text,
    estado       public.estado_registro
                 DEFAULT 'ACTIVO' NOT NULL,

    CONSTRAINT pk_ui
        PRIMARY KEY (id_ui),

    CONSTRAINT unq_ui_nombre
        UNIQUE (nombre_ui)
);

---------------------------------------------------
-- ui_permiso
---------------------------------------------------

CREATE TABLE public.ui_permiso (
    id_ui       integer NOT NULL,
    id_permiso  integer NOT NULL,
    estado      public.estado_registro NOT NULL,

    CONSTRAINT pk_ui_permiso
        PRIMARY KEY (id_ui, id_permiso),

    CONSTRAINT fk_ui_permiso_ui
        FOREIGN KEY (id_ui)
        REFERENCES public.ui(id_ui),

    CONSTRAINT fk_ui_permiso_permiso
