---------------------------------------------------
-- usuario
---------------------------------------------------

CREATE TABLE public.usuario (
    id_usuario        uuid DEFAULT gen_random_uuid() NOT NULL,
    nombre            varchar(50) NOT NULL,
    apellido_paterno  varchar(30) NOT NULL,
    apellido_materno  varchar(30),
    correo            varchar(100) NOT NULL,
    contrasenia       varchar(256) NOT NULL,
    cod_sis           varchar(15) NOT NULL,
    estado            public.estado_registro NOT NULL,

    CONSTRAINT pk_usuario
        PRIMARY KEY (id_usuario),

    CONSTRAINT unq_usuario_cod_sis
        UNIQUE (cod_sis),

    CONSTRAINT unq_usuario_correo
        UNIQUE (correo)
);

COMMENT ON TABLE public.usuario IS
'Para la sesión de los usuarios; tipos: Admin, docente y auxiliar';

---------------------------------------------------
-- usuario_rol
---------------------------------------------------

CREATE TABLE public.usuario_rol (
    id_usuario    uuid NOT NULL,
    id_rol        integer NOT NULL,
    fecha_inicio  timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    fecha_fin     timestamptz,

    CONSTRAINT pk_usuario_rol
        PRIMARY KEY (id_usuario, id_rol, fecha_inicio),

    CONSTRAINT fk_usuario_rol_usuario
        FOREIGN KEY (id_usuario)
        REFERENCES public.usuario(id_usuario),

    CONSTRAINT fk_usuario_rol_rol
        FOREIGN KEY (id_rol)
        REFERENCES public.rol(id_rol),

    CONSTRAINT chk_usuario_rol_fechas
        CHECK (fecha_fin IS NULL OR fecha_fin >= fecha_inicio)
);

---------------------------------------------------
-- log
---------------------------------------------------

CREATE TABLE public.log (
    id_log          bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_accion       integer,
    antiguo_valor   jsonb,
    nuevo_valor     jsonb,
    fecha_hora      timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    tabla_afectada  varchar NOT NULL,
    id_usuario 		uuid NOT NULL,

    CONSTRAINT pk_log
        PRIMARY KEY (id_log),

    CONSTRAINT fk_log_accion
        FOREIGN KEY (id_accion)
        REFERENCES public.accion(id_accion),
		
	CONSTRAINT fk_log_usuario
        FOREIGN KEY (id_usuario)
        REFERENCES public.usuario(id_usuario)
);

---------------------------------------------------
-- carrera
---------------------------------------------------

CREATE TABLE public.carrera (
    id_carrera   integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nombre       varchar(50) NOT NULL,
    codigo       varchar(50) NOT NULL,
    descripcion  text,
    estado       public.estado_registro
                 DEFAULT 'ACTIVO' NOT NULL,
    id_facultad  integer NOT NULL,

    CONSTRAINT pk_carrera
        PRIMARY KEY (id_carrera),

    CONSTRAINT unq_carrera_codigo
        UNIQUE (codigo),

    CONSTRAINT fk_carrera_facultad
        FOREIGN KEY (id_facultad)
        REFERENCES public.facultad(id_facultad)
);

---------------------------------------------------
-- convocatoria_admision
---------------------------------------------------

CREATE TABLE public.convocatoria_admision (
    id_admision   integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_facultad   integer NOT NULL,
    id_periodo    integer NOT NULL,
    gestion       varchar(10) NOT NULL,
    nro_opciones  varchar(2) NOT NULL,
    estado        public.estado_registro NOT NULL,

    CONSTRAINT pk_convocatoria_admision
        PRIMARY KEY (id_admision),

    CONSTRAINT fk_convocatoria_admision_facultad
        FOREIGN KEY (id_facultad)
        REFERENCES public.facultad(id_facultad),

    CONSTRAINT fk_convocatoria_admision_periodo
        FOREIGN KEY (id_periodo)
        REFERENCES public.periodo(id_periodo)
);

---------------------------------------------------
-- examen
---------------------------------------------------

CREATE TABLE public.examen (
    id_examen       integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    nombre_examen   varchar(25) NOT NULL,
    fecha           date NOT NULL,
    hora_inicio     time NOT NULL,
    hora_fin        time,
    duracion        integer,
    normas          text,
    id_tipo_examen  integer NOT NULL,
    id_carrera          integer,
    id_materia          integer,
    id_usuario_docente  uuid NOT NULL,
    estado              public.estado_examen
                        DEFAULT 'PROGRAMADO' NOT NULL,

    CONSTRAINT pk_examen
        PRIMARY KEY (id_examen),

    CONSTRAINT fk_examen_tipo_examen
        FOREIGN KEY (id_tipo_examen)
        REFERENCES public.tipo_examen(id_tipo_examen),

    CONSTRAINT fk_examen_usuario_docente
        FOREIGN KEY (id_usuario_docente)
        REFERENCES public.usuario(id_usuario),

    -- fk_examen_materia_carrera se declara después de crear materia_carrera.

    -- El par materia-carrera va completo o no va: un examen de admisión no tiene materia.
    CONSTRAINT chk_examen_materia_carrera
        CHECK ((id_carrera IS NULL) = (id_materia IS NULL)),

    -- hora_fin se deriva de la duración. Un examen que cruza la medianoche termina
    -- con una hora menor a la de inicio, por eso no se exige hora_fin > hora_inicio.
    CONSTRAINT chk_examen_hora_fin
        CHECK (
            hora_fin IS NULL
            OR duracion IS NULL
            OR hora_fin = hora_inicio + make_interval(mins => duracion)
        ),

    -- Menos de un día: la hora de fin no puede dar la vuelta completa al reloj.
    CONSTRAINT chk_examen_duracion
        CHECK (duracion IS NULL OR (duracion > 0 AND duracion < 1440))
);

---------------------------------------------------
-- examen_admision
---------------------------------------------------

CREATE TABLE public.examen_admision (
    id_admision  integer NOT NULL,
    id_examen    integer NOT NULL,
    nro_opcion   varchar(2) NOT NULL,

    CONSTRAINT pk_examen_admision
        PRIMARY KEY (id_admision, id_examen),

    CONSTRAINT unq_examen_admision_id_examen
        UNIQUE (id_examen),

    CONSTRAINT unq_examen_admision_nro_opcion
        UNIQUE (id_admision, nro_opcion),

    CONSTRAINT fk_examen_admision_convocatoria_admision
        FOREIGN KEY (id_admision)
        REFERENCES public.convocatoria_admision(id_admision),

    CONSTRAINT fk_examen_admision_examen
        FOREIGN KEY (id_examen)
        REFERENCES public.examen(id_examen)
);

---------------------------------------------------
-- examen_ambiente
---------------------------------------------------

CREATE TABLE public.examen_ambiente (
    id_examen    integer NOT NULL,
    id_ambiente  integer NOT NULL,

    CONSTRAINT pk_examen_ambiente
        PRIMARY KEY (id_examen, id_ambiente),

    CONSTRAINT fk_examen_ambiente_examen
        FOREIGN KEY (id_examen)
        REFERENCES public.examen(id_examen),

    CONSTRAINT fk_examen_ambiente_ambiente
        FOREIGN KEY (id_ambiente)
        REFERENCES public.ambiente(id_ambiente)
);

---------------------------------------------------
-- examen_postulante
---------------------------------------------------

CREATE TABLE public.examen_postulante (
    id_examen           integer NOT NULL,
    id_postulante       integer NOT NULL,
    estado_habilitacion public.estado_habilitacion NOT NULL,
    estado_ingreso      public.estado_ingreso NOT NULL,
    hora_ingreso        time,

    CONSTRAINT pk_examen_postulante
        PRIMARY KEY (id_examen, id_postulante),

    CONSTRAINT fk_examen_postulante_examen
        FOREIGN KEY (id_examen)
        REFERENCES public.examen(id_examen),

    CONSTRAINT fk_examen_postulante_postulante
        FOREIGN KEY (id_postulante)
        REFERENCES public.postulante(id_postulante),

    CONSTRAINT chk_examen_postulante_hora_ingreso
    CHECK (
        (
            estado_ingreso IN ('INGRESO', 'CON_RETRASO')
            AND hora_ingreso IS NOT NULL
        )
        OR
        (
            estado_ingreso = 'NO_INGRESO'
            AND hora_ingreso IS NULL
        )
    )
);

---------------------------------------------------
-- invitacion_examen
---------------------------------------------------

CREATE TABLE public.invitacion_examen (
    id_invitacion        integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_examen             integer NOT NULL,
    id_docente_creador    uuid NOT NULL,
    id_docente_invitado   uuid NOT NULL,
    fecha_invitacion      timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    fecha_respuesta       timestamptz,
    estado                public.estado_invitacion NOT NULL,

    CONSTRAINT pk_invitacion_examen
        PRIMARY KEY (id_invitacion),

    CONSTRAINT fk_invitacion_examen_examen
        FOREIGN KEY (id_examen)
        REFERENCES public.examen(id_examen),

    CONSTRAINT fk_invitacion_examen_docente_creador
        FOREIGN KEY (id_docente_creador)
        REFERENCES public.usuario(id_usuario),

    CONSTRAINT fk_invitacion_examen_docente_invitado
        FOREIGN KEY (id_docente_invitado)
        REFERENCES public.usuario(id_usuario),

    CONSTRAINT chk_invitacion_examen_fechas
        CHECK (
            fecha_respuesta IS NULL
            OR fecha_respuesta >= fecha_invitacion
        ),

    CONSTRAINT chk_invitacion_examen_estado
        CHECK (
            (estado = 'PENDIENTE' AND fecha_respuesta IS NULL)
            OR
            (estado IN ('ACEPTADA', 'RECHAZADA') AND fecha_respuesta IS NOT NULL)
        )
);

---------------------------------------------------
-- materia_carrera
---------------------------------------------------

CREATE TABLE public.materia_carrera (
    id_carrera      integer NOT NULL,
    id_materia      integer NOT NULL,
    nivel_semestre  varchar(15),
    obligatoria     boolean,
    estado          public.estado_registro
                    DEFAULT 'ACTIVO' NOT NULL,

    CONSTRAINT pk_materia_carrera
        PRIMARY KEY (id_carrera, id_materia),

    CONSTRAINT fk_materia_carrera_carrera
        FOREIGN KEY (id_carrera)
        REFERENCES public.carrera(id_carrera),

    CONSTRAINT fk_materia_carrera_materia
        FOREIGN KEY (id_materia)
        REFERENCES public.materia(id_materia)
);

-- examen se crea antes que materia_carrera: su clave compuesta hacia el par se agrega aquí,
-- igual que la de grupo.
ALTER TABLE public.examen
    ADD CONSTRAINT fk_examen_materia_carrera
        FOREIGN KEY (id_carrera, id_materia)
        REFERENCES public.materia_carrera(id_carrera, id_materia);

---------------------------------------------------
-- permiso_rol
---------------------------------------------------

CREATE TABLE public.permiso_rol (
    id_permiso  integer NOT NULL,
    id_rol      integer NOT NULL,
    estado      public.estado_registro NOT NULL,

    CONSTRAINT pk_permiso_rol
        PRIMARY KEY (id_permiso, id_rol),

    CONSTRAINT fk_permiso_rol_permiso
        FOREIGN KEY (id_permiso)
        REFERENCES public.permiso(id_permiso),

    CONSTRAINT fk_permiso_rol_rol
        FOREIGN KEY (id_rol)
        REFERENCES public.rol(id_rol)
);

---------------------------------------------------
-- reporte_estudiante
---------------------------------------------------

CREATE TABLE public.reporte_estudiante (
    id_reporte_est        integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_estudiante         integer NOT NULL,
    id_examen             integer NOT NULL,
    id_tipo_falta         integer NOT NULL,
    id_usuario_reportante uuid NOT NULL,
    descripcion           text,
    evidencia_url         text NOT NULL,
    evidencia_public_id   varchar NOT NULL,
    fecha_reporte         timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    estado                public.estado_reporte NOT NULL,
    fecha_revision       timestamptz,
    observacion_revision  text,
    id_usuario_revisor    uuid,

    CONSTRAINT pk_reporte_estudiante
        PRIMARY KEY (id_reporte_est),

    CONSTRAINT fk_reporte_estudiante_tipo_falta
        FOREIGN KEY (id_tipo_falta)
        REFERENCES public.tipo_falta(id_falta),

    CONSTRAINT fk_reporte_estudiante_estudiante
        FOREIGN KEY (id_estudiante)
        REFERENCES public.estudiante(id_estudiante),

    CONSTRAINT fk_reporte_estudiante_examen
        FOREIGN KEY (id_examen)
        REFERENCES public.examen(id_examen),

    CONSTRAINT fk_reporte_estudiante_usuario_reportante
        FOREIGN KEY (id_usuario_reportante)
        REFERENCES public.usuario(id_usuario),

    CONSTRAINT fk_reporte_estudiante_usuario_revisor
        FOREIGN KEY (id_usuario_revisor)
        REFERENCES public.usuario(id_usuario),

    CONSTRAINT chk_reporte_estudiante_revision
    CHECK (
        (
            estado = 'PENDIENTE'
            AND fecha_revision IS NULL
            AND id_usuario_revisor IS NULL
        )
        OR
        (
            estado IN ('APROBADO', 'RECHAZADO')
            AND fecha_revision IS NOT NULL
            AND id_usuario_revisor IS NOT NULL
        )
    )
);

---------------------------------------------------
-- reporte_postulante
---------------------------------------------------

CREATE TABLE public.reporte_postulante (
    id_reporte_post       integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_postulante         integer NOT NULL,
    id_examen             integer NOT NULL,
    id_tipo_falta         integer NOT NULL,
    id_usuario_reportante uuid NOT NULL,
    descripcion           text,
    evidencia_url         text NOT NULL,
    evidencia_public_id   varchar NOT NULL,
    fecha_reporte         timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
    estado                public.estado_reporte NOT NULL,
    fecha_revision        timestamptz,
    observacion_revision  text,
    id_usuario_revisor    uuid,

    CONSTRAINT pk_reporte_postulante
        PRIMARY KEY (id_reporte_post),

    CONSTRAINT fk_reporte_postulante_tipo_falta
        FOREIGN KEY (id_tipo_falta)
        REFERENCES public.tipo_falta(id_falta),

    CONSTRAINT fk_reporte_postulante_postulante
        FOREIGN KEY (id_postulante)
        REFERENCES public.postulante(id_postulante),

    CONSTRAINT fk_reporte_postulante_examen
        FOREIGN KEY (id_examen)
        REFERENCES public.examen(id_examen),

    CONSTRAINT fk_reporte_postulante_usuario_reportante
        FOREIGN KEY (id_usuario_reportante)
        REFERENCES public.usuario(id_usuario),

    CONSTRAINT fk_reporte_postulante_usuario_revisor
        FOREIGN KEY (id_usuario_revisor)
        REFERENCES public.usuario(id_usuario),

    CONSTRAINT chk_reporte_postulante_revision
    CHECK (
        (
            estado = 'PENDIENTE'
            AND fecha_revision IS NULL
            AND id_usuario_revisor IS NULL
        )
        OR
        (
            estado IN ('APROBADO', 'RECHAZADO')
            AND fecha_revision IS NOT NULL
            AND id_usuario_revisor IS NOT NULL
        )
    )
);

---------------------------------------------------
-- sesion
---------------------------------------------------

CREATE TABLE public.sesion (
    id_sesion      integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_usuario     uuid NOT NULL,
    pid            integer NOT NULL,
    ip_direccion   inet NOT NULL,
    num_puerto     integer NOT NULL,
