    CONSTRAINT unq_central_riesgo_id_reporte
        UNIQUE (id_reporte_est),

    CONSTRAINT fk_central_riesgo_reporte_estudiante
        FOREIGN KEY (id_reporte_est)
        REFERENCES public.reporte_estudiante(id_reporte_est),

    CONSTRAINT fk_central_riesgo_estudiante
        FOREIGN KEY (id_estudiante)
        REFERENCES public.estudiante(id_estudiante)
);

---------------------------------------------------
-- central_riesgo_postulante
---------------------------------------------------

CREATE TABLE public.central_riesgo_postulante (
    id_cr_postulante  integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_reporte_post   integer NOT NULL,
    id_postulante     integer NOT NULL,
    fecha_registro    timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,

    CONSTRAINT pk_central_riesgo_postulante
        PRIMARY KEY (id_cr_postulante),

    CONSTRAINT unq_central_riesgo_postulante_id_reporte
        UNIQUE (id_reporte_post),

    CONSTRAINT fk_central_riesgo_postulante_reporte
        FOREIGN KEY (id_reporte_post)
        REFERENCES public.reporte_postulante(id_reporte_post),

    CONSTRAINT fk_central_riesgo_postulante_postulante
        FOREIGN KEY (id_postulante)
        REFERENCES public.postulante(id_postulante)
);

---------------------------------------------------
-- grupo
---------------------------------------------------

CREATE TABLE public.grupo (
    id_grupo            integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    id_carrera          integer NOT NULL,
    id_materia          integer NOT NULL,
    num_grupo           varchar (5) NOT NULL,
    gestion             varchar(10) NOT NULL,
    estado              public.estado_registro
                        DEFAULT 'ACTIVO' NOT NULL,
    id_usuario_docente  uuid NOT NULL,
    id_periodo          integer NOT NULL,

    CONSTRAINT pk_grupo
        PRIMARY KEY (id_grupo),

    CONSTRAINT fk_grupo_materia_carrera
        FOREIGN KEY (id_carrera, id_materia)
        REFERENCES public.materia_carrera(id_carrera, id_materia),

    CONSTRAINT fk_grupo_usuario_docente
        FOREIGN KEY (id_usuario_docente)
        REFERENCES public.usuario(id_usuario),

    CONSTRAINT fk_grupo_periodo
        FOREIGN KEY (id_periodo)
        REFERENCES public.periodo(id_periodo),
		
	CONSTRAINT unq_grupo
    UNIQUE (
        id_carrera,
        id_materia,
        num_grupo,
        gestion,
        id_periodo
    )
);

---------------------------------------------------
-- grupo_estudiante
---------------------------------------------------

CREATE TABLE public.grupo_estudiante (
    id_grupo          integer NOT NULL,
    id_estudiante     integer NOT NULL,
    fecha_inscripcion date NOT NULL,
    estado            public.estado_registro NOT NULL,

    CONSTRAINT pk_grupo_estudiante
        PRIMARY KEY (id_grupo, id_estudiante),

    CONSTRAINT fk_grupo_estudiante_grupo
        FOREIGN KEY (id_grupo)
        REFERENCES public.grupo(id_grupo),

    CONSTRAINT fk_grupo_estudiante_estudiante
        FOREIGN KEY (id_estudiante)
        REFERENCES public.estudiante(id_estudiante)
);

---------------------------------------------------
-- grupo_examen
---------------------------------------------------

CREATE TABLE public.grupo_examen (
    id_grupo   integer NOT NULL,
    id_examen  integer NOT NULL,

    CONSTRAINT pk_grupo_examen
        PRIMARY KEY (id_grupo, id_examen),

    CONSTRAINT fk_grupo_examen_grupo
        FOREIGN KEY (id_grupo)
        REFERENCES public.grupo(id_grupo),

    CONSTRAINT fk_grupo_examen_examen
        FOREIGN KEY (id_examen)
        REFERENCES public.examen(id_examen)
);

---------------------------------------------------
-- examen_estudiante
---------------------------------------------------

CREATE TABLE public.examen_estudiante (
    id_examen            integer NOT NULL,
    id_estudiante        integer NOT NULL,
    estado_habilitacion  public.estado_habilitacion NOT NULL,
    observacion          text,
    estado_ingreso       public.estado_ingreso NOT NULL,
    hora_ingreso         time,
    id_grupo             integer NOT NULL,

    CONSTRAINT pk_examen_estudiante
        PRIMARY KEY (id_examen, id_estudiante),

    CONSTRAINT fk_examen_estudiante_examen
        FOREIGN KEY (id_examen)
        REFERENCES public.examen(id_examen),

    CONSTRAINT fk_examen_estudiante_estudiante
        FOREIGN KEY (id_estudiante)
        REFERENCES public.estudiante(id_estudiante),
		
	CONSTRAINT fk_examen_estudiante_grupo_examen
    	FOREIGN KEY (id_grupo, id_examen)
    	REFERENCES public.grupo_examen(id_grupo, id_examen),

	CONSTRAINT fk_examen_estudiante_grupo_estudiante
	    FOREIGN KEY (id_grupo, id_estudiante)
	    REFERENCES public.grupo_estudiante(id_grupo, id_estudiante),

    CONSTRAINT chk_examen_estudiante_hora_ingreso
    CHECK (
        (
            estado_ingreso IN ('INGRESO', 'CON_RETRASO')
            AND hora_ingreso IS NOT NULL
        )
        OR
        (
            estado_ingreso = 'NO_INGRESO'
            AND hora_ingreso IS NULL
        )
    )
);

